function getLocalMerumputProgress(estateId = "FPM_TUNGGAL") {
  if (fs4.existsSync(MERUMPUT_PROGRESS_FILE)) {
    try {
      const stored = JSON.parse(fs4.readFileSync(MERUMPUT_PROGRESS_FILE, "utf-8"));
      if (stored && Array.isArray(stored) && stored.length > 0) {
        let isModified = false;
        const migrated = stored.map((item) => {
          if (item.blok === "LF" && item.pusingan === 1 && item.jenis === "BULATAN & LORONG" && item.tarikh_mula === "2026-02-05") {
            isModified = true;
            return {
              ...item,
              tarikh_mula: "2026-01-10",
              tarikh_siap: "2026-01-10",
              updated_at: (/* @__PURE__ */ new Date()).toISOString()
            };
          }
          return item;
        });
        if (isModified) {
          saveLocalMerumputProgress(migrated);
          return migrated;
        }
        const hasEstateRecords = stored.some(
          (item) => estateId === "FPM_TUNGGAL" ? !item.estate_id || item.estate_id === "FPM_TUNGGAL" : item.estate_id === estateId
        );
        if (!hasEstateRecords) {
          const newEstateSeed = getInitialSeedData(estateId);
          const combined = [...stored, ...newEstateSeed];
          saveLocalMerumputProgress(combined);
          return combined;
        }
        return stored;
      }
    } catch (e) {
      console.error("Error reading merumput data", e);
    }
  }
  const initial = [...getInitialSeedData("FPM_TUNGGAL"), ...getInitialSeedData("FPM_ADELA")];
  saveLocalMerumputProgress(initial);
  return initial;
}
