function getLocalEstateJson(prefix, estateId = "FPM_TUNGGAL", defaultValue = null) {
  const safeEstate = (estateId || "FPM_TUNGGAL").replace(/[^a-zA-Z0-9_-]/g, "_");
  const filePath = path4.join(DATA_DIR, `${prefix}_${safeEstate}.json`);
  if (fs4.existsSync(filePath)) {
    try {
      return JSON.parse(fs4.readFileSync(filePath, "utf-8"));
    } catch (e) {
      console.error(`Error reading ${filePath}`, e);
    }
  }
  if (safeEstate === "FPM_TUNGGAL") {
    const legacyPath = path4.join(DATA_DIR, `${prefix}.json`);
    if (fs4.existsSync(legacyPath)) {
      try {
        return JSON.parse(fs4.readFileSync(legacyPath, "utf-8"));
      } catch (e) {
      }
    }
  }
  return defaultValue;
}
function saveLocalEstateJson(prefix, estateId = "FPM_TUNGGAL", data) {
  try {
    const safeEstate = (estateId || "FPM_TUNGGAL").replace(/[^a-zA-Z0-9_-]/g, "_");
    const filePath = path4.join(DATA_DIR, `${prefix}_${safeEstate}.json`);
    fs4.writeFileSync(filePath, JSON.stringify(data, null, 2), "utf-8");
    if (safeEstate === "FPM_TUNGGAL") {
      const legacyPath = path4.join(DATA_DIR, `${prefix}.json`);
      fs4.writeFileSync(legacyPath, JSON.stringify(data, null, 2), "utf-8");
    }
  } catch (e) {
    console.error(`Error saving local estate json for ${prefix} (${estateId})`, e);
  }
}

