// src/server/utils/errorUtils.ts
var AppError = class extends Error {
  constructor(message, statusCode = 500, code = "INTERNAL_ERROR", details) {
    super(message);
    this.name = this.constructor.name;
    this.statusCode = statusCode;
    this.code = code;
    this.details = details;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
};
var ValidationError = class extends AppError {
  constructor(message, details) {
    super(message, 400, "VALIDATION_ERROR", details);
  }
};
function getErrorMessage(error) {
  if (error instanceof Error) {
    return error.message;
  }
  if (typeof error === "string") {
    return error;
  }
  if (error && typeof error === "object") {
    if ("message" in error && typeof error.message === "string") {
      return String(error.message);
    }
    if ("error" in error && typeof error.error === "string") {
      return String(error.error);
    }
    if ("error_description" in error && typeof error.error_description === "string") {
      return String(error.error_description);
    }
    try {
      return JSON.stringify(error);
    } catch {
      return "An unexpected error occurred";
    }
  }
  return "An unexpected error occurred";
}
function getSafeErrorMessage(error, fallback = "Ralat dalaman pelayan. Sila cuba lagi.") {
  if (error instanceof AppError) {
    return error.message;
  }
  return fallback;
}
function getErrorStatusCode(error, defaultCode = 500) {
  if (error instanceof AppError) {
    return error.statusCode;
  }
  if (error && typeof error === "object") {
    const code = error.statusCode || error.status;
    if (typeof code === "number" && code >= 100 && code <= 599) {
      return code;
    }
  }
  return defaultCode;
}

