function generateAdelaBaselineTransactions() {
  const transactions = [];
  const monthDates = [
    "2026-01-20",
    "2026-02-18",
    "2026-03-22",
    "2026-04-19",
    "2026-05-21",
    "2026-06-20",
    "2026-07-24",
    "2026-08-25"
  ];
  const lorries = ["JTG4421", "JQR8823", "JPM1902", "JTK9031", "JNA5540", "JSD2291"];
  ADELA_BLOCK_PERINCIAN.forEach((blockItem) => {
    blockItem.monthlyTons.slice(0, 8).forEach((ton, mIdx) => {
      const dateStr = monthDates[mIdx] || `2026-0${mIdx + 1}-15`;
      const lorry = lorries[(mIdx + parseInt(blockItem.blok.replace(/\D/g, "") || "1")) % lorries.length];
      const receiptNo = `ADL-2026-M0${mIdx + 1}-${blockItem.blok.toUpperCase()}`;
      const kpg = mIdx >= 3 ? "21.50" : "21.20";
      const rmMt = 780 + mIdx * 15;
      const hasilRm = parseFloat((ton * rmMt).toFixed(2));
      transactions.push({
        no_resit: receiptNo,
        no_akaun_terima: `ADL-${blockItem.blok}`,
        no_lori: lorry,
        no_nota_hantaran: `NH-ADL-0${mIdx + 1}-${blockItem.blok}`,
        kpg,
        blok: blockItem.blok,
        peringkat: blockItem.peringkat,
        tan: parseFloat(ton.toFixed(2)),
        muda: 0,
        reject: 0,
        sample: 100,
        rm_mt: rmMt,
        hasil_rm: hasilRm,
        thek: parseFloat((ton / blockItem.luas).toFixed(4)),
        tarikh: dateStr,
        masa_masuk: "10:30:00",
        estate_id: "FPM_ADELA",
        created_at: `${dateStr}T10:30:00.000Z`
      });
    });
  });
  return transactions;
}

// src/utils/formatters.ts
function cleanAndExtractBlockCode(raw) {
  if (!raw) return "";
  let s = String(raw).trim().toUpperCase();
  if (!s) return "";
  const btsMatch = s.match(/\b\d{4}(?:-[0-9A-Z]+)+-([0-9]{1,3}[A-Z]?)\b/);
  if (btsMatch) {
    return btsMatch[1];
  }
  const pMatch = s.match(/^(?:P(?:KT)?\s*([12]))\s*[-:\s]\s*(?:BLOK\s*[-:]?\s*)?([0-9]{1,3}[A-Z]?)/i);
  if (pMatch) {
    return `P${pMatch[1]}-${pMatch[2]}`;
  }
  if (/\b(?:5136[-\s]+001[-\s]+(?:(?:3|88)[-\s]+)?(?:88\s*F|88|F88)|88\s*F|F\s*88)\b/i.test(s) || s === "88F" || s === "88 F" || s === "F88") {
    return "88F";
  }
  s = s.replace(/^(?:BLOK|BLOCK|B)\s*[-:]?\s*/i, "").trim();
  if (/^[0-9]{1,3}\s*[-/ ]\s*(?:FELDA|LADANG|FPM|RANCANGAN|ADELA|TUNGGAL|KLEDANG|SENING)/i.test(s) || /(?:FELDA|LADANG|RANCANGAN)/i.test(s)) {
    return "";
  }
  const validSingleBlock = s.match(/^([0-9]{1,3}[A-Z]?|[1-9][A-Z]?|LF)$/i);
  if (validSingleBlock) {
    return validSingleBlock[1];
  }
  const blockStartMatch = s.match(/^([0-9]{1,3}[A-Z]?)/);
  if (blockStartMatch && blockStartMatch[1]) {
    return blockStartMatch[1];
  }
  return s;
}

