// src/server/services/pdfIngestion.service.ts
init_db();
function generateHierarchicalIngestionChunks(pages, fileName, category, documentId, minTokens = 500, maxTokens = 800, overlapPct = 0.12) {
  const CHARS_PER_TOKEN = 4;
  const maxCharLimit = maxTokens * CHARS_PER_TOKEN;
  const overlapCharLimit = Math.floor(maxCharLimit * Math.min(0.15, Math.max(0.1, overlapPct)));
  const chunks = [];
  let chunkGlobalIndex = 0;
  for (const page of pages) {
    const rawText = (page.text || "").trim();
    if (!rawText) continue;
    const pageNum = page.pageNum;
    const extractionMethod = page.isOcr ? "ocr" : "digital";
    const isTableContent = /\|.*\|.*\||(?:\d+[\.\,]\d+\s+){3,}/i.test(rawText) || rawText.includes("JADUAL") || rawText.includes("KUK Siri");
    const isFormulaContent = /RM\s*\d+|[\+\=\/\*]\s*\d+%/i.test(rawText);
    const contentType = isTableContent ? "table" : isFormulaContent ? "formula" : "text";
    const headingMatch = rawText.match(/^(?:#{1,4}\s+|BAB\s+\d+|SEKSYEN\s+\d+|MANUAL\s+|JADUAL\s+\d+)([^\n]+)/i);
    const sectionTitle = headingMatch ? headingMatch[0].trim() : `${fileName.replace(/\.pdf$/i, "")} - M/S ${pageNum}`;
    const paragraphs = rawText.split(/\n\s*\n/);
    let currentBlock = "";
    for (const para of paragraphs) {
      const cleanPara = para.trim();
      if (!cleanPara) continue;
      if ((currentBlock + "\n\n" + cleanPara).length <= maxCharLimit) {
        currentBlock = currentBlock ? `${currentBlock}

${cleanPara}` : cleanPara;
      } else {
        if (currentBlock) {
          chunks.push({
            chunkIndex: chunkGlobalIndex++,
            pageNumber: pageNum,
            sectionTitle,
            content: currentBlock.trim(),
            contentType,
            extractionMethod,
            metadata: {
              document_id: documentId,
              file_name: fileName,
              category,
              page_number: pageNum,
              section: sectionTitle,
              chunk_index: chunkGlobalIndex - 1,
              content_type: contentType,
              extraction_method: extractionMethod
            }
          });
          const tail = currentBlock.slice(-overlapCharLimit);
          currentBlock = `... ${tail}

${cleanPara}`;
        } else {
          const sentences = cleanPara.match(/[^.!?]+[.!?]+(\s+|$)/g) || [cleanPara];
          let sentChunk = "";
          for (const sentence of sentences) {
            if ((sentChunk + sentence).length <= maxCharLimit) {
              sentChunk += sentence;
            } else {
              chunks.push({
                chunkIndex: chunkGlobalIndex++,
                pageNumber: pageNum,
                sectionTitle,
                content: sentChunk.trim(),
                contentType,
                extractionMethod,
                metadata: {
                  document_id: documentId,
                  file_name: fileName,
                  category,
                  page_number: pageNum,
                  section: sectionTitle,
                  chunk_index: chunkGlobalIndex - 1,
                  content_type: contentType,
                  extraction_method: extractionMethod
                }
              });
              const tailSent = sentChunk.slice(-overlapCharLimit);
              sentChunk = `... ${tailSent}${sentence}`;
            }
          }
          currentBlock = sentChunk;
        }
      }
    }
    if (currentBlock.trim()) {
      chunks.push({
        chunkIndex: chunkGlobalIndex++,
        pageNumber: pageNum,
        sectionTitle,
        content: currentBlock.trim(),
        contentType,
        extractionMethod,
        metadata: {
          document_id: documentId,
          file_name: fileName,
          category,
          page_number: pageNum,
          section: sectionTitle,
          chunk_index: chunkGlobalIndex - 1,
          content_type: contentType,
          extraction_method: extractionMethod
        }
      });
    }
  }
  return chunks;
}
