      const has020Bts = combinedBtsSerial.includes("-020-") || /\b\d{4}-020-/.test(combinedBtsSerial) || /[-_]020[-_]/.test(combinedBtsSerial) || /\b020\b/.test(parsed.kod_akaun_bts || "");
