function formatApprovalTime(iso) {
  if (!iso) return "Tidak diketahui";
  const d = new Date(iso);
  if (isNaN(d.getTime())) return "Tidak diketahui";
  try {
    return d.toLocaleString("en-GB", {
      timeZone: "Asia/Kuala_Lumpur",
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    });
  } catch {
    return d.toISOString();
  }
}
